323  // Create a cache with type-specific hash/compare/destruct/size functions
   324  Cache *ass_cache_create(const CacheDesc *desc)
   325  {
   326      Cache *cache = calloc(1, sizeof(*cache));
   327      if (!cache)
   328          return NULL;
   329      cache->buckets = 0xFFFF;
   330      cache->queue_last = &cache->queue_first;
   331      cache->desc = desc;
   332      cache->map = calloc(cache->buckets, sizeof(CacheItem *));
   333      if (!cache->map) {
   334          free(cache);
   335          return NULL;
   336      }
   337
   338      return cache;
   339  }
