   341  void *ass_cache_get(Cache *cache, void *key, void *priv)
   342  {
   343      const CacheDesc *desc = cache->desc;
   344      size_t key_offs = CACHE_ITEM_SIZE + align_cache(desc->value_size);
   345      unsigned bucket = desc->hash_func(key, FNV1_32A_INIT) % cache->buckets;
   346      CacheItem *item = cache->map[bucket];
   347      while (item) {
   348          if (desc->compare_func(key, (char *) item + key_offs)) {
   349              assert(item->size);
   350              if (!item->queue_prev || item->queue_next) {
   351                  if (item->queue_prev) {
   352                      item->queue_next->queue_prev = item->queue_prev;
   353                      *item->queue_prev = item->queue_next;
   354                  } else
   355                      item->ref_count++;
